import React, { useState } from 'react';
import { api } from '../services/api';

const Register = ({ onRegister, onSwitchToLogin }) => {
  const [formData, setFormData] = useState({
    nombre: '',
    correo: '',
    password: '',
    confirmPassword: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    // Validar que las contraseñas coincidan
    if (formData.password !== formData.confirmPassword) {
      setError('Las contraseñas no coinciden');
      return;
    }

    setLoading(true);

    try {
      // Enviar solo los datos necesarios con rol fijo de ESTUDIANTE
      const registroData = {
        nombre: formData.nombre,
        correo: formData.correo,
        password: formData.password,
        rol: 'ESTUDIANTE'
      };

      const response = await api.post('/usuarios/registro', registroData);
      if (response.data.success) {
        alert('✅ Registro exitoso. Por favor inicia sesión.');
        onRegister();
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Error al registrar');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center px-4 py-12 bg-gradient-to-br from-cyan-500 via-blue-600 to-purple-600">
      <div className="max-w-2xl w-full animate-fadeIn">
        <div className="text-center mb-8">
          <div className="text-7xl mb-6 animate-pulse-soft">🎓</div>
          <h2 className="text-4xl font-extrabold text-white mb-2 tracking-tight">
            Registro de Estudiante
          </h2>
          <p className="text-cyan-100 text-lg font-medium">
            Sistema de Gestión de Turnos - Laboratorios
          </p>
        </div>

        <div className="card-gradient p-10 shadow-2xl">
          <form onSubmit={handleSubmit} className="space-y-6">
            {error && (
              <div className="bg-gradient-to-r from-red-50 to-pink-50 border-2 border-red-300 rounded-xl p-4 text-red-700 text-sm font-medium animate-fadeIn">
                <span className="text-lg mr-2">⚠️</span>
                {error}
              </div>
            )}

            <div>
              <label className="block text-sm font-bold text-gray-700 mb-3 flex items-center">
                <span className="text-lg mr-2">👤</span>
                Nombre Completo *
              </label>
              <input
                type="text"
                value={formData.nombre}
                onChange={(e) => setFormData({...formData, nombre: e.target.value})}
                className="input-field text-base"
                placeholder="Ej: Juan Pérez García"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-bold text-gray-700 mb-3 flex items-center">
                <span className="text-lg mr-2">📧</span>
                Correo Electrónico *
              </label>
              <input
                type="email"
                value={formData.correo}
                onChange={(e) => setFormData({...formData, correo: e.target.value})}
                className="input-field text-base"
                placeholder="ejemplo@universidad.edu.co"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-bold text-gray-700 mb-3 flex items-center">
                <span className="text-lg mr-2">🔒</span>
                Contraseña * (mínimo 8 caracteres)
              </label>
              <input
                type="password"
                value={formData.password}
                onChange={(e) => setFormData({...formData, password: e.target.value})}
                className="input-field text-base"
                placeholder="••••••••"
                minLength="8"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-bold text-gray-700 mb-3 flex items-center">
                <span className="text-lg mr-2">🔐</span>
                Confirmar Contraseña *
              </label>
              <input
                type="password"
                value={formData.confirmPassword}
                onChange={(e) => setFormData({...formData, confirmPassword: e.target.value})}
                className="input-field text-base"
                placeholder="••••••••"
                minLength="8"
                required
              />
              {formData.confirmPassword && formData.password !== formData.confirmPassword && (
                <p className="text-sm text-red-600 mt-2 font-semibold flex items-center animate-fadeIn">
                  <span className="mr-2">⚠️</span>
                  Las contraseñas no coinciden
                </p>
              )}
              {formData.confirmPassword && formData.password === formData.confirmPassword && (
                <p className="text-sm text-green-600 mt-2 font-semibold flex items-center animate-fadeIn">
                  <span className="mr-2">✓</span>
                  Las contraseñas coinciden
                </p>
              )}
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full btn-primary text-lg py-4 font-bold"
            >
              {loading ? (
                <span className="flex items-center justify-center">
                  <span className="animate-spin mr-2">⏳</span>
                  Registrando...
                </span>
              ) : (
                <span className="flex items-center justify-center">
                  <span className="text-xl mr-2">✨</span>
                  Registrarse
                </span>
              )}
            </button>

            <div className="text-center pt-4 border-t-2 border-gray-200">
              <button
                type="button"
                onClick={onSwitchToLogin}
                className="text-purple-600 hover:text-purple-800 text-sm font-bold transition-colors duration-200"
              >
                ¿Ya tienes cuenta? <span className="underline">Inicia sesión aquí</span>
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Register;
